    func test_binary_broadcast() {
        check([3, 0], .Double, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, "x + MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])"){ x in x + MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) }
        check([3, 0], .Double, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, "x * MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])"){ x in x * MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) }
        check([3, 0], .Double, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, "x / MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])"){ x in x / MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) }
        check([3, 0], .Double, MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 0, atol: 0, "x > MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])"){ x in x > MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) }
        check([3, 0], .Double, MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 0, atol: 0, "x !== MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])"){ x in x !== MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) }
        check([3, 0], .Double, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, "Matft.stats.minimum(x, MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]))"){ x in Matft.stats.minimum(x, MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1])) }
        check([3, 0], .Double, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, "MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) + x"){ x in MfArray([1.0, 1.0, 1.0] as [Double], mftype: .Double, shape: [3, 1]) + x }
