    func test_scalar_and_unary() {
        check([0], .Double, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, "x + 1.5"){ x in x + 1.5 }
        check([0], .Double, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, "1.5 - x"){ x in 1.5 - x }
        check([0], .Double, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, "x * 2.0"){ x in x * 2.0 }
        check([0], .Double, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, "2.0 / x"){ x in 2.0 / x }
        check([0], .Double, MfArray([] as [Bool], mftype: .Bool, shape: [0]), rtol: 0, atol: 0, "x > 0.5"){ x in x > 0.5 }
        check([0], .Double, MfArray([] as [Bool], mftype: .Bool, shape: [0]), rtol: 0, atol: 0, "0.5 === x"){ x in 0.5 === x }
        check([0], .Double, MfArray([] as [Double], mftype: .Double, shape: [0]), rtol: 1e-10, atol: 1e-10, "-x"){ x in -x }
        check([0], .Float, MfArray([] as [Double], mftype: .Float, shape: [0]), rtol: 1e-05, atol: 1e-05, "x * Float(2)"){ x in x * Float(2) }
        check([0], .Float, MfArray([] as [Double], mftype: .Float, shape: [0]), rtol: 1e-05, atol: 1e-05, "Float(3) - x"){ x in Float(3) - x }
        check([0], .Float, MfArray([] as [Double], mftype: .Float, shape: [0]), rtol: 1e-05, atol: 1e-05, "-x"){ x in -x }
        check([0], .Int, MfArray([] as [Int], mftype: .Int, shape: [0]), rtol: 0, atol: 0, "x + 1"){ x in x + 1 }
